INSERT INTO feature VALUES('specification-monads','effects','Specification monads','effect-theories','partial','notable',NULL,'A program over state is specified by the predicate transformer its weakest-precondition observation computes, from a postcondition on the answer and the final state, and an initial state, to the precondition there (Maillard et al., ICFP 2019). The observation is a handler of state whose carrier is the transformers, its scope checked as a model of put-get, put-put and get-get; written as a fold of the program''s tree, the normaliser computes a precondition and the kernel replays it, and the increment pairs, in a dependent record, with evidence that its transformer is below its specification at one postcondition and at every postcondition; the stopped program pairs with evidence below the return specification at every postcondition. A specification monad is a theory whose order is a sort indexed by two computations, reflexive, transitive and with a monotone extension. The order named as a definition waits on #2759, a precondition through the scope on #2754, the monad''s laws beside its order on #4128, and get-put on #1934.',NULL,'corpus/model/specification/state-wp.gandr corpus/pathological/specification/state-wp.gandr corpus/model/specification/tree-state-wp.gandr corpus/pathological/specification/tree-state-wp.gandr corpus/model/specification/specification-monad.gandr corpus/pathological/specification/specification-monad.gandr corpus/model/effects/state.gandr corpus/pathological/effects/state.gandr','corpus/ledger/features/specification-monads.gandr','#2759 #2754 #1510');
